1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"unicode/utf8"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// submissionShape is the fixed-field shape of an audit submission: the agreed
112	// spellings at the top level and inside the artifact, every rule and every
113	// check record. The invariants object is a fixed top-level member but has no
114	// nested shape, so it passes through untouched: invariant names are
115	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
116	// independent invariants and a padded name is not trimmed.
117	var submissionShape = fixedShape{
118		keys: []string{"artifact", "rules", "invariants", "checks"},
119		objects: map[string]fixedShape{
120			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
121		},
122		arrays: map[string]fixedShape{
123			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
124			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
125		},
126	}
127	
128	// strictSubmissionJSON rewrites submission bytes to the fixed submission
129	// fields under their agreed spelling; see fixedShape for the recognition
130	// convention shared with the archive read side.
131	func strictSubmissionJSON(data []byte) ([]byte, error) {
132		return strictFixedJSON(data, submissionShape)
133	}
134	
135	// validateFormalCheckStatuses checks the formal "status" member of every
136	// strict check record. The strict rewrite dropped extension members, so the
137	// status seen here is the agreed-spelling one alone: a missing formal status,
138	// a non-string one, or an unsupported value rejects the whole submission
139	// even when an adjacent "StAtus" extension member carried a legal-looking
140	// value. The error names the rule the record is for so the offending entry is
141	// identifiable.
142	func validateFormalCheckStatuses(strict []byte) error {
143		var top struct {
144			Checks []map[string]json.RawMessage `json:"checks"`
145		}
146		if err := json.Unmarshal(strict, &top); err != nil {
147			return errInvalid("invalid JSON: " + err.Error())
148		}
149		for _, rec := range top.Checks {
150			where := "check record"
151			if raw, ok := rec["ruleId"]; ok {
152				var ruleID string
153				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
154					where = "check for rule " + ruleID
155				}
156			}
157			raw, ok := rec["status"]
158			if !ok {
159				return errInvalid(where + ": status is required")
160			}
161			var status string
162			if err := json.Unmarshal(raw, &status); err != nil {
163				return errInvalid(where + ": status must be a string")
164			}
165			if !validCheckStatus(status) {
166				return errInvalid(where + ": unknown status " + status)
167			}
168		}
169		return nil
170	}
171	
172	// ParseAuditInput decodes an audit submission JSON object into domain values.
173	// Invariant values must be JSON booleans; any other type is an error. Any JSON
174	// object in the submission that repeats a member name rejects the whole
175	// submission: the decoder keeps only the last value silently, so a repeated
176	// invariant key would choose a conclusion by member order instead of giving
177	// one trustworthy result. A character the decoder would silently rewrite — an
178	// invalid UTF-8 byte, or an unpaired or wrongly ordered surrogate escape in
179	// any member name or string value, including values nested under unknown
180	// extension members — rejects the whole submission as an input error before
181	// any content is hashed, so evidence and hashes always reflect the submitted
182	// bytes rather than a U+FFFD-rewritten copy. Only the fixed fields under their
183	// agreed spelling participate: case variants and whitespace-padded names are
184	// extension data and are ignored, so they can neither override a formal value
185	// nor supply one when the formal member is missing or unsupported. Invariant
186	// names are not fixed fields — they are user-defined, compared case
187	// sensitively and never trimmed.
188	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
189		if charErr := validateJSONCharacters(data); charErr != nil {
190			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
191		}
192		if dup := findDuplicateJSONMember(data); dup != nil {
193			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
194		}
195		strict, err := strictSubmissionJSON(data)
196		if err != nil {
197			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
198		}
199		if err := validateFormalCheckStatuses(strict); err != nil {
200			return Artifact{}, nil, nil, nil, err
201		}
202		var in wireInput
203		if err := json.Unmarshal(strict, &in); err != nil {
204			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
205		}
206		invariants := make(map[string]bool, len(in.Invariants))
207		for key, raw := range in.Invariants {
208			// Only JSON true/false is a conclusion. Unmarshalling directly into a
209			// bool would turn null into the zero value false, which would falsely
210			// record a defect; require the token to be a boolean instead.
211			var token any
212			if err := json.Unmarshal(raw, &token); err != nil {
213				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
214			}
215			holds, ok := token.(bool)
216			if !ok {
217				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
218			}
219			invariants[key] = holds
220		}
221		artifact := Artifact{
222			Name:     in.Artifact.Name,
223			ABI:      in.Artifact.ABI,
224			Bytecode: in.Artifact.Bytecode,
225			Source:   in.Artifact.Source,
226		}
227		rules := make([]Rule, 0, len(in.Rules))
228		for _, wr := range in.Rules {
229			rules = append(rules, Rule{
230				ID:          wr.ID,
231				Kind:        wr.Kind,
232				Severity:    wr.Severity,
233				Invariant:   wr.Invariant,
234				RequiresABI: wr.RequiresABI,
235				Version:     wr.Version,
236			})
237		}
238		checks := make([]CheckRecord, 0, len(in.Checks))
239		for _, wc := range in.Checks {
240			checks = append(checks, CheckRecord{
241				ArtifactHash: wc.ArtifactHash,
242				RuleID:       wc.RuleID,
243				Version:      wc.Version,
244				Status:       wc.Status,
245				Note:         wc.Note,
246			})
247		}
248		return artifact, rules, invariants, checks, nil
249	}
250	
251	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
252	// bytecode and source strings contribute; field boundaries are explicit
253	// (length-prefixed) so that different splits never collide. The source is
254	// hashed as a field value, never read from disk, and the name does not
255	// participate.
256	func ArtifactHash(a Artifact) string {
257		h := sha256.New()
258		h.Write([]byte("contractsentinel-artifact-v1\n"))
259		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
260			fmt.Fprintf(h, "%d\n", len(field))
261			h.Write([]byte(field))
262		}
263		sum := h.Sum(nil)
264		return hex.EncodeToString(sum)
265	}
266	
267	// validCheckStatus reports whether status is one of the four recorded check
268	// conclusions.
269	func validCheckStatus(status string) bool {
270		switch status {
271		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
272			return true
273		}
274		return false
275	}
276	
277	// BuildReport evaluates rules against the artifact and invariant values and
278	// imported check records and produces the report to persist. Insufficient
279	// inputs (missing ABI for a rule that requires it, missing bytecode for a
280	// symbolic rule) fail the whole submission and are never recorded as defects.
281	// Imported checks are validated as a whole: unknown rules, duplicate records,
282	// unknown statuses, missing notes, hash or version mismatches, and a rule
283	// receiving both a check record and an invariant boolean all reject the
284	// submission without producing a report.
285	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
286		if artifact.Name == "" {
287			return Report{}, errInvalid("artifact name is required")
288		}
289		hash := ArtifactHash(artifact)
290		seen := make(map[string]bool, len(rules))
291		ruleByID := make(map[string]Rule, len(rules))
292		for _, rule := range rules {
293			if rule.ID == "" {
294				return Report{}, errInvalid("rule id is required")
295			}
296			if rule.Version == "" {
297				return Report{}, errInvalid("rule " + rule.ID + " version is required")
298			}
299			if seen[rule.ID] {
300				return Report{}, errInvalid("duplicate rule id " + rule.ID)
301			}
302			seen[rule.ID] = true
303			ruleByID[rule.ID] = rule
304			if rule.RequiresABI && artifact.ABI == "" {
305				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
306			}
307			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
308				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
309			}
310		}
311		checkByRule := make(map[string]CheckRecord, len(checks))
312		for _, check := range checks {
313			if check.RuleID == "" {
314				return Report{}, errInvalid("check rule id is required")
315			}
316			rule, ok := ruleByID[check.RuleID]
317			if !ok {
318				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
319			}
320			if _, dup := checkByRule[check.RuleID]; dup {
321				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
322			}
323			if check.ArtifactHash != hash {
324				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
325			}
326			if check.Version != rule.Version {
327				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
328			}
329			if !validCheckStatus(check.Status) {
330				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
331			}
332			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
333				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
334			}
335			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
336				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
337			}
338			checkByRule[check.RuleID] = check
339		}
340		report := Report{
341			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
342			Rules:    []ReportRule{},
343			Findings: []ReportFinding{},
344		}
345		for _, rule := range rules {
346			status := StatusUnchecked
347			note := ""
348			if check, ok := checkByRule[rule.ID]; ok {
349				status = check.Status
350				note = check.Note
351			} else if holds, checked := invariants[rule.Invariant]; checked {
352				if holds {
353					status = StatusPass
354				} else {
355					status = StatusDefect
356				}
357			}
358			report.Rules = append(report.Rules, ReportRule{
359				ID:          rule.ID,
360				Kind:        rule.Kind,
361				Severity:    rule.Severity,
362				Invariant:   rule.Invariant,
363				RequiresABI: rule.RequiresABI,
364				Version:     rule.Version,
365				Status:      status,
366				Note:        note,
367			})
368			if status == StatusDefect {
369				evidence := note
370				if evidence == "" {
371					evidence = "invariant " + rule.Invariant + " does not hold"
372				}
373				report.Findings = append(report.Findings, ReportFinding{
374					ArtifactHash: hash,
375					RuleID:       rule.ID,
376					Version:      rule.Version,
377					Severity:     rule.Severity,
378					Invariant:    rule.Invariant,
379					Evidence:     evidence,
380				})
381			}
382		}
383		report.ReportID = ReportID(report)
384		return report, nil
385	}
386	
387	// canonicalRule is the order-independent view of a rule used for the id. The
388	// note is omitted when empty so reports built only from invariant booleans
389	// keep their original ids.
390	type canonicalRule struct {
391		ID          string `json:"id"`
392		Kind        string `json:"kind"`
393		Severity    string `json:"severity"`
394		Invariant   string `json:"invariant"`
395		RequiresABI bool   `json:"requiresABI"`
396		Version     string `json:"version"`
397		Status      string `json:"status"`
398		Note        string `json:"note,omitempty"`
399	}
400	
401	// canonicalFinding is the order-independent view of a finding used for the id.
402	type canonicalFinding struct {
403		ArtifactHash string `json:"artifactHash"`
404		RuleID       string `json:"ruleId"`
405		Version      string `json:"version"`
406		Severity     string `json:"severity"`
407		Invariant    string `json:"invariant"`
408		Evidence     string `json:"evidence"`
409	}
410	
411	// canonicalReport is the deterministic content a report id is computed from.
412	type canonicalReport struct {
413		ArtifactHash string             `json:"artifactHash"`
414		Name         string             `json:"name"`
415		Rules        []canonicalRule    `json:"rules"`
416		Findings     []canonicalFinding `json:"findings"`
417	}
418	
419	// canonicalize renders a report into its order-independent form.
420	func canonicalize(report Report) canonicalReport {
421		cr := canonicalReport{
422			ArtifactHash: report.Artifact.Hash,
423			Name:         report.Artifact.Name,
424		}
425		for _, rule := range report.Rules {
426			cr.Rules = append(cr.Rules, canonicalRule{
427				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
428				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
429				Version: rule.Version, Status: rule.Status, Note: rule.Note,
430			})
431		}
432		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
433		for _, finding := range report.Findings {
434			cr.Findings = append(cr.Findings, canonicalFinding{
435				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
436				Version: finding.Version, Severity: finding.Severity,
437				Invariant: finding.Invariant, Evidence: finding.Evidence,
438			})
439		}
440		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
441		return cr
442	}
443	
444	// ReportID returns the content-addressed identifier of a report. The id binds
445	// the artifact hash, name, complete rule definitions, the invariant value
446	// used by each rule (unchecked and explicit pass are distinct), and the
447	// findings. Rule order, invariant key order and unrelated invariant keys do
448	// not influence it.
449	func ReportID(r Report) string {
450		data, err := json.Marshal(canonicalize(r))
451		if err != nil {
452			panic(err) // canonical values are all strings and bools
453		}
454		sum := sha256.Sum256(data)
455		return hex.EncodeToString(sum[:])
456	}
457	
458	// validateReport checks every archive legality condition against r. It is the
459	// single definition of a legal report: the id and artifact hash are 64
460	// lowercase hex characters, the id matches the content, the artifact name is
461	// present, rule ids are present and unique with non-empty versions, statuses
462	// use the five recorded values, tool-missing and timeout notes are
463	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
464	// artifact hash, version, severity, invariant and evidence match the rule.
465	// The same conditions apply to submissions and to stored archives: a
466	// recomputed id never makes an invalid report legal. fail is errInvalid for
467	// submissions and errCorrupt for stored archives.
468	func validateReport(r Report, fail func(string) error) error {
469		if !validReportID(r.ReportID) {
470			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
471		}
472		if r.Artifact.Name == "" {
473			return fail("report " + r.ReportID + " artifact name is required")
474		}
475		if !validReportID(r.Artifact.Hash) {
476			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
477		}
478		if ReportID(r) != r.ReportID {
479			return fail("report content does not match id " + r.ReportID)
480		}
481		seenRule := make(map[string]bool, len(r.Rules))
482		defectByID := make(map[string]ReportRule)
483		for _, rule := range r.Rules {
484			if rule.ID == "" {
485				return fail("report " + r.ReportID + " has a rule with an empty id")
486			}
487			if seenRule[rule.ID] {
488				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
489			}
490			seenRule[rule.ID] = true
491			if rule.Version == "" {
492				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
493			}
494			switch rule.Status {
495			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
496			default:
497				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
498			}
499			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
500				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
501			}
502			if rule.Status == StatusDefect {
503				defectByID[rule.ID] = rule
504			}
505		}
506		seenFinding := make(map[string]bool, len(r.Findings))
507		for _, f := range r.Findings {
508			if f.RuleID == "" {
509				return fail("report " + r.ReportID + " has a finding with an empty rule id")
510			}
511			rule, ok := defectByID[f.RuleID]
512			if !ok {
513				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
514			}
515			if seenFinding[f.RuleID] {
516				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
517			}
518			seenFinding[f.RuleID] = true
519			if f.ArtifactHash != r.Artifact.Hash {
520				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
521			}
522			if f.Version != rule.Version {
523				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
524			}
525			if f.Severity != rule.Severity {
526				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
527			}
528			if f.Invariant != rule.Invariant {
529				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
530			}
531			wantEvidence := rule.Note
532			if wantEvidence == "" {
533				wantEvidence = "invariant " + rule.Invariant + " does not hold"
534			}
535			if f.Evidence != wantEvidence {
536				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
537			}
538		}
539		for id := range defectByID {
540			if !seenFinding[id] {
541				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
542			}
543		}
544		return nil
545	}
546	
547	// validStoredReport validates archive contents.
548	func validStoredReport(r Report) error {
549		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
550	}
551	
552	// validSubmittedReport validates a submission before any store operation.
553	func validSubmittedReport(r Report) error {
554		return validateReport(r, func(msg string) error { return errInvalid(msg) })
555	}
556	
557	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
558	// inside s. A Go string can carry any bytes, including bytes no JSON text may
559	// contain: json.Marshal (and therefore the canonical marshalling inside
560	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
561	// neither the id/content check nor the archive round trip can see it.
562	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
563		for i := 0; i < len(s); {
564			r, size := utf8.DecodeRuneInString(s[i:])
565			if r == utf8.RuneError && size == 1 {
566				return s[i], true
567			}
568			i += size
569		}
570		return 0, false
571	}
572	
573	// validateSubmittedText is the in-memory counterpart of the JSON character
574	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
575	// built directly by a Go caller, whose strings never passed through JSON
576	// decoding; encoding/json marshals such a value without an error while
577	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
578	// the same rewritten canonical form, so the recomputed id and the
579	// rule/finding correspondence would all match an archive whose text no
580	// longer equals what the caller handed over. Every caller-supplied string is
581	// therefore checked on the raw object — reportId, artifact name and hash,
582	// each rule definition field and status note, and each finding binding field
583	// and evidence — independently of which rules produced defects and of
584	// whether the report carries any finding at all. The rejection is an input
585	// error naming the exact field, with the array position of rules and
586	// findings, and it runs before any filesystem operation.
587	func validateSubmittedText(r Report) error {
588		check := func(field, value string) error {
589			if b, bad := firstInvalidUTF8ByteInString(value); bad {
590				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
591			}
592			return nil
593		}
594		if err := check("reportId", r.ReportID); err != nil {
595			return err
596		}
597		if err := check("artifact.name", r.Artifact.Name); err != nil {
598			return err
599		}
600		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
601			return err
602		}
603		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
604		for i, rule := range r.Rules {
605			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
606			for j, value := range values {
607				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
608					return err
609				}
610			}
611		}
612		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
613		for i, finding := range r.Findings {
614			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
615			for j, value := range values {
616				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
617					return err
618				}
619			}
620		}
621		return nil
622	}
623	
624	// duplicateArchiveError classifies an archive that repeats a JSON member as
625	// corrupt and names the requested report id, the decoded member name and the
626	// object carrying it (with array position and rule id when applicable).
627	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
628		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
629	}
630	
631	// characterArchiveError classifies an archive whose bytes are not legal JSON
632	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
633	// surrogate escape inside any member name or string value, including unknown
634	// extension members — as corrupt and names the requested report id together
635	// with the precise byte offset, line/column and JSON path. It is the
636	// read-side counterpart of the submission gate in ParseAuditInput: the decode
637	// below would otherwise replace both problems with U+FFFD and could accept a
638	// rewritten archive whose id and rule/finding evidence happened to match.
639	func characterArchiveError(id string, charErr *charEncodingError) error {
640		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
641	}
642	
643	// reportShape is the fixed-field shape of a stored report archive: the agreed
644	// spellings at the top level and inside the artifact, every rule and every
645	// finding. The trusted content of a report is carried by these fixed fields
646	// alone; case variants, whitespace-padded names and unknown members are
647	// extension data and never reach the decoder.
648	var reportShape = fixedShape{
649		keys: []string{"reportId", "artifact", "rules", "findings"},
650		objects: map[string]fixedShape{
651			"artifact": {keys: []string{"name", "hash"}},
652		},
653		arrays: map[string]fixedShape{
654			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
655			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
656		},
657	}
658	
659	// strictReportJSON rewrites archive bytes to the fixed report fields under
660	// their original spelling; see fixedShape for the recognition convention
661	// shared with the submission side.
662	func strictReportJSON(data []byte) ([]byte, error) {
663		return strictFixedJSON(data, reportShape)
664	}
665	
666	// loadStoredReport parses archive bytes for id and fully validates them.
667	func loadStoredReport(data []byte, id string) (Report, error) {
668		// Read-side counterpart of the submission character gate in
669		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
670		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
671		// surrogate escape into U+FFFD, so an archive whose note and evidence both
672		// carried the substitution character could have those two spots changed to
673		// lone surrogate escapes and still decode to byte-identical content: the
674		// recomputed id and the rule/finding evidence comparison would then pass on
675		// the rewritten copy. Every raw string literal is checked first — member
676		// names and values, at every depth, inside unknown extension members too —
677		// and the whole archive is corrupt when any character is illegal, whatever
678		// id the rewritten content would compute.
679		if charErr := validateJSONCharacters(data); charErr != nil {
680			return Report{}, characterArchiveError(id, charErr)
681		}
682		// Read-side counterpart of the submission check: json.Unmarshal silently
683		// keeps the last value for a repeated member, so an archive that writes a
684		// rule status as 发现缺陷 and then 通过 would decode to whichever came
685		// last. The recomputed id and the rule/finding correspondence all operate
686		// on that last-wins value and could therefore pass, accepting an archive
687		// with two conflicting conclusions. Any repeated member in any object
688		// makes the archive corrupt, regardless of the last value.
689		if dup := findDuplicateJSONMember(data); dup != nil {
690			return Report{}, duplicateArchiveError(id, data, dup)
691		}
692		strict, err := strictReportJSON(data)
693		if err != nil {
694			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
695		}
696		var r Report
697		if err := json.Unmarshal(strict, &r); err != nil {
698			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
699		}
700		if r.ReportID != id {
701			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
702		}
703		if err := validStoredReport(r); err != nil {
704			return Report{}, err
705		}
706		return r, nil
707	}
708	
709	// saveReportHook, when set, is invoked after the archive existence check and
710	// before the atomic publish. It lets tests simulate another process racing to
711	// claim the same report id.
712	var saveReportHook func(finalPath string)
713	
714	// SaveReport persists a report under the store directory. The store is safe
715	// for concurrent writers: identical reports share one file and all
716	// submissions succeed, different reports never overwrite each other, and
717	// readers only ever observe complete files. A submission is fully validated
718	// before any store operation, so an invalid report creates no store and no
719	// files. Every string in a directly constructed report must be valid UTF-8:
720	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
721	// content-addressed id matched the rewritten copy, reporting success for an
722	// archive whose text differs from the caller's; such a report is rejected as
723	// an input error before the store directory is touched. A pre-existing file
724	// with the same id must be a valid archive of the same report; a corrupted
725	// archive makes the submission fail while keeping the original file, even
726	// when the corruption appears only during the save. The first successfully
727	// archived bytes are never replaced by later submissions.
728	func SaveReport(dir string, r Report) error {
729		if err := validateSubmittedText(r); err != nil {
730			return err
731		}
732		if err := validSubmittedReport(r); err != nil {
733			return err
734		}
735		if err := os.MkdirAll(dir, 0o755); err != nil {
736			return err
737		}
738		finalPath := filepath.Join(dir, r.ReportID+".json")
739		if existing, err := os.ReadFile(finalPath); err == nil {
740			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
741				return err
742			}
743			return nil
744		} else if !os.IsNotExist(err) {
745			return err
746		}
747		data, err := json.Marshal(r)
748		if err != nil {
749			return err
750		}
751		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
752		if err != nil {
753			return err
754		}
755		tmpPath := tmp.Name()
756		cleanup := func() { os.Remove(tmpPath) }
757		if _, err := tmp.Write(data); err != nil {
758			tmp.Close()
759			cleanup()
760			return err
761		}
762		if err := tmp.Sync(); err != nil {
763			tmp.Close()
764			cleanup()
765			return err
766		}
767		if err := tmp.Close(); err != nil {
768			cleanup()
769			return err
770		}
771		if saveReportHook != nil {
772			saveReportHook(finalPath)
773		}
774		if err := os.Link(tmpPath, finalPath); err != nil {
775			cleanup()
776			if os.IsExist(err) {
777				existing, readErr := os.ReadFile(finalPath)
778				if readErr != nil {
779					return readErr
780				}
781				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
782					return err
783				}
784				return nil
785			}
786			return err
787		}
788		cleanup()
789		return nil
790	}
791	
792	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
793	// hex characters; missing, corrupted or tampered archives produce a clear
794	// error. The store is only read, never created or modified.
795	func LoadReport(dir, id string) (Report, error) {
796		if !validReportID(id) {
797			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
798		}
799		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
800		if err != nil {
801			if os.IsNotExist(err) {
802				return Report{}, errNotFound("report " + id + " not found")
803			}
804			return Report{}, err
805		}
806		return loadStoredReport(data, id)
807	}
808	
809	type errNotFound string
810	
811	func (e errNotFound) Error() string { return string(e) }
812	
813	type errCorrupt string
814	
815	func (e errCorrupt) Error() string { return string(e) }
816

