1	package contractsentinel
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件锁定 audit 提交侧的固定字段大小写规则，与 report 读取侧
11	// (report_strict_load_test.go) 保持一致：只有约定拼写的字段参与审计，
12	// StAtus、Version、RULES 这类大小写变体以及名称两侧带空格的成员都只是扩展
13	// 信息，出现在正式成员之前或之后、携带任意合法 JSON 类型都不能改写结论；
14	// 但扩展信息本身仍被允许，不能一遇未知名称就拒绝。不变式名称是用户定义的，
15	// Inv 与 inv 是两个独立不变式，名称空格也不修剪。字段名的 JSON 转义按解码
16	// 后的名称识别；重复成员（含扩展对象内部）仍整份拒绝。
17	
18	// strictTestArtifact 是本文件提交用例共享的产物，其 JSON 形态与字段值固定。
19	func strictTestArtifact() Artifact {
20		return Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
21	}
22	
23	const strictArtifactJSON = `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`
24	const strictRulesJSON = `[{"id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":false,"version":"1.0.0"}]`
25	
26	// strictDoc 用顶层段落拼装一份提交，括号由本函数统一负责，避免手写时漏掉
27	// 外层大括号。
28	func strictDoc(sections ...string) string {
29		return "{" + strings.Join(sections, ",") + "}"
30	}
31	
32	// strictDefectCheck 是一条绑定正确产物哈希、正式结论为“发现缺陷”的检查
33	// 记录；formalPrefix 会被放在正式 status 之前（用于在正式字段前放扩展成员），
34	// formalSuffix 放在其后。
35	func strictDefectCheck(hash, formalPrefix, formalSuffix string) string {
36		return fmt.Sprintf(
37			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0",%s"status":"发现缺陷"%s,"note":"counterexample: x"}`,
38			hash, formalPrefix, formalSuffix)
39	}
40	
41	// strictParsedReport 解析并构建一份提交，返回报告；任一环节失败即终止。
42	func strictParsedReport(t *testing.T, in string) Report {
43		t.Helper()
44		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
45		if err != nil {
46			t.Fatalf("legal submission must parse: %v\ninput: %s", err, in)
47		}
48		report, err := BuildReport(artifact, rules, invariants, checks)
49		if err != nil {
50			t.Fatalf("legal submission must build a report: %v\ninput: %s", err, in)
51		}
52		return report
53	}
54	
55	// --- 核心场景：正式 status=发现缺陷 + StAtus=通过，两种成员顺序结论一致 ---
56	
57	func TestParseAuditCaseVariantStatusKeepsDefect(t *testing.T) {
58		hash := ArtifactHash(strictTestArtifact())
59		plain := strictDoc(
60			`"artifact":`+strictArtifactJSON,
61			`"rules":`+strictRulesJSON,
62			`"checks":[`+strictDefectCheck(hash, "", "")+`]`,
63		)
64		want := strictParsedReport(t, plain)
65	
66		for _, tc := range []struct {
67			name   string
68			prefix string
69			suffix string
70		}{
71			{"variant after formal field", "", `,"StAtus":"通过"`},
72			{"variant before formal field", `"StAtus":"通过",`, ""},
73		} {
74			t.Run(tc.name, func(t *testing.T) {
75				in := strictDoc(
76					`"artifact":`+strictArtifactJSON,
77					`"rules":`+strictRulesJSON,
78					`"checks":[`+strictDefectCheck(hash, tc.prefix, tc.suffix)+`]`,
79				)
80				got := strictParsedReport(t, in)
81	
82				// 正式缺陷仍生成该规则的缺陷。
83				if len(got.Findings) != 1 {
84					t.Fatalf("findings = %d, want 1 (formal 发现缺陷)", len(got.Findings))
85				}
86				f := got.Findings[0]
87				if f.RuleID != "r1" || f.Version != "1.0.0" || f.ArtifactHash != hash {
88					t.Fatalf("finding binding changed: %+v", f)
89				}
90				if f.Evidence != "counterexample: x" {
91					t.Fatalf("formal note evidence must be preserved, got %q", f.Evidence)
92				}
93				if got.Rules[0].Status != StatusDefect {
94					t.Fatalf("rule status = %q, want %q", got.Rules[0].Status, StatusDefect)
95				}
96				// 仅增加扩展信息不得改变报告标识、产物哈希与规则版本绑定。
97				if got.ReportID != want.ReportID {
98					t.Fatalf("extension member changed the report id:\n got %s\nwant %s", got.ReportID, want.ReportID)
99				}
100				if got.Artifact.Hash != hash {
101					t.Fatalf("artifact hash changed: %q", got.Artifact.Hash)
102				}
103			})
104		}
105	}
106	
107	// --- 扩展成员携带任意合法 JSON 类型、位于正式字段前后，都不改变合法结果 ---
108	
109	func TestParseAuditExtensionMembersOfAnyTypeIgnored(t *testing.T) {
110		hash := ArtifactHash(strictTestArtifact())
111		values := []string{`"通过"`, `123`, `true`, `null`, `[1,2,3]`, `{"a":1}`}
112		for _, val := range values {
113			for _, pos := range []string{"before", "after"} {
114				ext := `"StAtus":` + val
115				var middle string
116				var suffix string
117				if pos == "before" {
118					middle = ext + ","
119				} else {
120					suffix = "," + ext
121				}
122				check := fmt.Sprintf(
123					`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0",%s"status":"发现缺陷"%s,"note":"ce"}`,
124					hash, middle, suffix)
125				in := strictDoc(
126					`"artifact":`+strictArtifactJSON,
127					`"rules":`+strictRulesJSON,
128					`"checks":[`+check+`]`,
129				)
130				got := strictParsedReport(t, in)
131				if len(got.Findings) != 1 || got.Rules[0].Status != StatusDefect {
132					t.Fatalf("ext=%s pos=%s changed the conclusion: %+v", val, pos, got)
133				}
134			}
135		}
136	}
137	
138	// --- 顶层、产物、规则、检查记录的大小写变体都不能替代正式字段 ---
139	
140	func TestParseAuditCaseVariantsIgnoredAtEveryLevel(t *testing.T) {
141		hash := ArtifactHash(strictTestArtifact())
142		// 正式输入：规则 r1 版本 1.0.0、不变式 inv=false，应产生一个缺陷；检查
143		// 记录给 r1 一条正式“通过”会与不变式冲突，所以这里只在顶层放变体检查。
144		in := strictDoc(
145			// 产物：大小写变体给出不同名字与字段，正式产物不受影响。
146			`"artifact":{`+
147				`"Name":"Other","ABI":"other-abi","BYTECODE":"0xffff","Source":"Other.sol",`+
148				`"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`,
149			// 规则：变体 RULES 用 9.9.9 版本，正式 rules 仍是 1.0.0；规则内
150			// Version/ID 变体也被忽略。
151			`"RULES":[{"id":"r1","version":"9.9.9"}]`,
152			`"rules":[{"ID":"x","Version":"9.9.9","id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":false,"version":"1.0.0"}]`,
153			// 顶层变体检查记录携带别的结论，正式 checks 为空，不影响。
154			`"CHECKS":[{"ruleId":"r1","StAtus":"通过"}]`,
155			`"invariants":{"inv":false}`,
156		)
157		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
158		if err != nil {
159			t.Fatalf("legal submission must parse: %v", err)
160		}
161		// 正式产物的四个字段都必须来自约定拼写，变体里的 other-* 一律忽略。
162		if artifact != strictTestArtifact() {
163			t.Fatalf("artifact fields came from case variants: %+v", artifact)
164		}
165		got, err := BuildReport(artifact, rules, invariants, checks)
166		if err != nil {
167			t.Fatalf("legal submission must build a report: %v", err)
168		}
169		if got.Artifact.Name != "Vault" {
170			t.Fatalf("artifact name came from a case variant: %+v", got.Artifact)
171		}
172		if got.Artifact.Hash != hash {
173			t.Fatalf("artifact hash changed via variants: %q want %q", got.Artifact.Hash, hash)
174		}
175		if got.Rules[0].Version != "1.0.0" || got.Rules[0].ID != "r1" {
176			t.Fatalf("rule fields came from case variants: %+v", got.Rules[0])
177		}
178		if len(got.Findings) != 1 || got.Findings[0].Version != "1.0.0" {
179			t.Fatalf("formal inv=false must bind rule version 1.0.0: %+v", got.Findings)
180		}
181	
182		// 与不含任何扩展成员的同一提交报告标识一致。
183		plain := strictDoc(
184			`"artifact":`+strictArtifactJSON,
185			`"rules":`+strictRulesJSON,
186			`"invariants":{"inv":false}`,
187		)
188		want := strictParsedReport(t, plain)
189		if got.ReportID != want.ReportID {
190			t.Fatalf("extensions changed the report id:\n got %s\nwant %s", got.ReportID, want.ReportID)
191		}
192	}
